            profit = max(profit, prices[i] - minStock);
        }

        return profit;
    }
};

int maxSubArray(vector<int>& nums) {
    int global = nums[0];
    int local = 0;

    int N = nums.size();

    for(int i = 0; i < N; i++) {
        local = max(local + nums[i], nums[i]);
        global = max(global, local);
    }

    return global;
}

class Solution {
public:
    string crackSafe(int n, int k) {

        if(n == 1 && k == 1) return "0";

        // Store the edges of graph.
        unordered_set<string> M; 

        string start = string(n - 1, '0');
        string ans = "";

        function<void(string)> euler = [&](string u) {      
            for(char c = '0'; c < k + '0'; c++) {
                // How to use the last sequence optimally
                string v = u + c;

                // We don't have to visit the same edge again
                if(M.count(v)) continue;
                M.insert(v);

                euler(v.substr(1));

                ans.push_back(c);
            }
        };

        euler(start);

        return ans + start;
    }
};

class Solution {
public:
    bool validPath(int n, vector<vector<int>>& edges, int source, int destination) {

        // Creation of Graph
        unordered_map<int, vector<int>> G;

        for(auto &e : edges) {
            int u = e[0], v = e[1];
            G[u].push_back(v);
            G[v].push_back(u);
        }

        // BFS

        queue<int> q;
        vector<int> seen(n, 0); // 0 ->unseen

        q.push(source);
        seen[source] = 1;

        while(q.size()) {
            int v = q.front();
            q.pop();
            // Traverse every edge of v in breadth first search

            for(int u : G[v]) {
                if(seen[u]) continue;
                seen[u] = 1;
                q.push(u);
            }
        }

        if(seen[destination] == 1) {
            return true;
        } else {
            return false;
        }
    }
};

class Solution {
public:

    ListNode* reverseList(ListNode* head) {
        ListNode *prev = new ListNode();

        while(head) {
            auto node = head;
            head = head->next;
            node->next = prev->next;
            prev->next = node;
        }

        return prev->next;
    }

    vector<int> nextLargerNodes(ListNode* head) {
        head = reverseList(head);

        stack<int> S;
        vector<int> ans;


        while(head) {

            int n = head->val;

            while(S.size() && S.top() <= n) {
                S.pop();
            }

            if(S.size() == 0) {
                ans.push_back(0);
            } else {
                ans.push_back(S.top());
            }

            S.push(n);

            head = head->next;
        }

        reverse(ans.begin(), ans.end());
        return ans;
    }
};

