        int dp[amount + 1];
        dp[0] = 0;

        sort(coins.begin(), coins.end());

        for(int i = 1; i <= amount; i++) {

            dp[i] = INT_MAX;
            for(auto &coin : coins) {
                if(i - coin < 0) break;

                if(dp[i - coin] != INT_MAX) {
                    dp[i] = min(dp[i], 1 + dp[i - coin]);
                }
            }
        }

        if(dp[amount] != INT_MAX) {
            return dp[amount];
        } else {
            return -1;
        }
    }
};

