class Solution {
public:
    int maxFrequency(vector<int>& A, int k) {
        int N = A.size();

        sort(A.begin(), A.end());

        long ans = 1, sum = 0, i = 0;

        for(int j = 0; j < N; j++) {
            sum += A[j];

            // Increase the left boundary of window :
            // (Length of window * currentElement) - Sum of all elements > k 
            while( (j - i + 1) * A[j] - sum > k) {
                sum -= A[i++];
            }

            ans = max(ans, j - i + 1);

        }

        return ans;
    }
};

