        // This cell of grid has been visited.
        grid[i][j] = '2';

        // Go to the four sides of grid.
        for(auto &dir : dirs) {
            int a = i + dir[0];
            int b = j + dir[1];

            if(a < 0 || b < 0 || a >= M || b >= N || grid[a][b] != '1') continue;

            dfs(grid, a, b);
        }
