        M = grid.size();
        N = grid[0].size();

        int islandCnt = 0;

        for(int i = 0; i < M; i++) {
            for(int j = 0; j < N; j++) {
                if(grid[i][j] == '1') {
                    dfs(grid, i, j);
                    islandCnt++;
                }
            }
        }

        return islandCnt;
    }
};

