    int M, N;
    vector<vector<int>> dp;

    bool wildcardMatching(string &s, string &p, int i, int j) {

        if(dp[i][j] != -1) return dp[i][j]; 
        int &ans = dp[i][j];

        for(; j < N; j++) {

            if(p[j] != '*' && i >= M) return ans = false;
            if(p[j] == '?') {
                i++;
            } else if(p[j] == '*') {
                while(j + 1 < N && p[j + 1] == '*') j++;
                for(int k = 0; i + k <= M; i++) {
                    if(wildcardMatching(s, p, i + k, j + 1)) {
                        return ans = true;
                    }
                }
            } else if(s[i++] != p[j]) {
                return ans = false;
            }
        }

        return ans = i >= M;

    }

    bool isMatch(string s, string p) {
        M = s.size();
        N = p.size();

        dp.assign(M + 1, vector<int>(N + 1, -1));
        return wildcardMatching(s, p, 0, 0);
    }
};

class MinStack {
public:

    stack<int> S, M;

    void push(int val) {
        S.push(val);
        if(M.empty() || M.top() >= val) {
            M.push(val);
        }
    }

    void pop() {
        int x = S.top();
        S.pop();

        // If popped element is minimum
        if(M.top() == x) {
            M.pop();
        }
    }

    int top() {
        return S.top();
    }

    int getMin() {
        return M.top();
    }
};

class Solution {
public:

    vector<vector<int>> ans;

    void permute(vector<int> &nums, int start) {
        // Base case
        if(start == nums.size()) {
            ans.push_back(nums);
            return;
        }

        for(int i = start; i < nums.size(); i++) {
            swap(nums[start], nums[i]);
            permute(nums, start + 1);
            swap(nums[start], nums[i]);
        }

    }

    vector<vector<int>> permute(vector<int>& nums) {
        permute(nums, 0);
        return ans;
    }
};

class Solution {
public:

    vector<vector<int>> ans;

    void combine(vector<int> &temp, int n, int k, int start) {
        // Base case
        if(temp.size() == k) {
            ans.push_back(temp);
            return;
        }

        for(int i = start, end = n - k + temp.size(); i <= end; i++) {
            temp.push_back(i + 1);
            combine(temp, n, k, i + 1);
            temp.pop_back();
        }
    }

    vector<vector<int>> combine(int n, int k) {
        vector<int> temp;
        combine(temp, n, k, 0);
        return ans;
    }
};

