int peakIndexInMountainArray(vector<int>& arr) {
    int N = arr.size();

    int L = 1, R = N - 2, M;

    while(L <= R) {
        M = (L + R) / 2;

        if(arr[M] > arr[M - 1]) {
            L = M + 1;
        } else {
            R = M - 1;
        }
    }

    return R;
}

