int findMin(vector<int>& nums) {
    int N = nums.size();

    int L = 0, R = N - 1, M;

    while(L < R) {
        M = (L + R) / 2;

        if(nums[M] < nums[R]) {
            R = M;
        } else {
            L = M + 1;
        }
    }

    return nums[R];
}

class Solution {
public:

    vector<vector<int>> ans;

    vector<vector<int>> zigzagLevelOrder(TreeNode* root) {
        if(!root) {
            return {};
        }

        bool l2r = true;

        queue<TreeNode*> q;
        q.push({root});

        while(q.size()) {
            int cnt = q.size();

            vector<int> temp;

            while(cnt--) {
                auto node = q.front();
                q.pop();

                temp.push_back(node->val);

                if(node->left) {
                    q.push(node->left);
                }

                if(node->right) {
                    q.push(node->right);
                }
            }

            if(!l2r) {
                reverse(temp.begin(), temp.end());
            }

            l2r = !l2r;
            ans.push_back(temp);
        }

        return ans;
    }
};

int lengthOfLongestSubstring(string s) {
    int N = s.length();
    int length = 0, i = 0;
    unordered_map<int, int> M;

    for(int j = 0; j < N; j++) {

        M[s[j]]++;

        // Increase the window size from left side if there are multiple characters
        while(M[s[j]] > 1) {
            M[s[i++]]--;
        }

        length = max(length, j - i + 1);
    }

    return length;
}

