class Solution {
public:
    vector<vector<int>> ans;
    void permute(vector<int> nums, int start) {
        if(start == nums.size() - 1) {
            ans.push_back(nums);
            return;
        }

        for(int i = start; i < nums.size(); i++) {
            if(i != start && nums[i] == nums[start]) continue;
            swap(nums[i], nums[start]);
            permute(nums, start + 1);
        }
    }

    vector<vector<int>> permuteUnique(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        permute(nums, 0);
        return ans;
    }
};

class Solution {
public:
    vector<vector<int>> combinationSum2(vector<int>& A, int target) {

        int N = A.size();
        sort(A.begin(), A.end());
        vector<vector<int>> ans;
        vector<int> temp;

        function<void(int, int)> dfs = [&](int start, int goal) {
            if(goal == 0) {
                ans.push_back(temp);
                return;
            }

            for(int i = start; i < N && goal - A[i] >= 0 ; i++) {
                if(i != start && A[i] == A[i - 1]) continue;
                temp.push_back(A[i]);
                dfs(i + 1, goal - A[i]);
                temp.pop_back();
            }
        };

        dfs(0, target);

        return ans;
    }
};

int eraseOverlapIntervals(vector<vector<int>>& intervals) {
    sort(intervals.begin(), intervals.end(), [](auto &a, auto &b) {
        return a[1] < b[1];
    });

    int overlapCnt = 0;
    int end = INT_MIN;

    for(auto &e : intervals) {
        if(e[0] >= end) {
            end = e[1];
        } else {
            overlapCnt++;
        }
    }

    return overlapCnt;
}

class Solution {
public:
    int maxProfit(vector<int>& A) {
        if (A.empty()) return 0;
        int N = A.size(), buy = INT_MIN;
        vector<int> dp(N + 1, 0);
        for (int i = 0; i < N; ++i) {
            buy = max(buy, (i >= 1 ? dp[i - 1] : 0) - A[i]);
            dp[i + 1] = max(dp[i], buy + A[i]);
        }
        return dp[N];
    }
};

class Solution {
public:
    int findMaximumXOR(vector<int>& A) {
        unordered_set<int> s;
        int mask = 0, ans = 0;
        for (int i = 31; i >= 0; --i) {
            mask |= 1 << i;
            s.clear();
            for (int n : A) s.insert(n & mask);
            int next = ans | (1 << i);
            for (int prefix : s) {
                if (!s.count(next ^ prefix)) continue;
                ans |= 1 << i;
                break;
            }
        }
        return ans;
    }
};

struct TrieNode {
    TrieNode *next[2] = {};
};
class Solution {
    void add(TrieNode *node, int n) {
        for (int i = 31; i >= 0; --i) {
            int b = n >> i & 1;
            if (node->next[b] == NULL) node->next[b] = new TrieNode();
            node = node->next[b];
        }
    }
    int maxXor(TrieNode *node, int n) {
        int ans = 0;
        for (int i = 31; i >= 0; --i) {
            int b = n >> i & 1;
            if (node->next[1 - b]) { // if we can go the opposite direction, do it.
                node = node->next[1 - b];
                ans |= 1 << i;
            } else {
                node = node->next[b];
            }
        }
        return ans;
    }
public:
    int findMaximumXOR(vector<int>& A) {
        TrieNode root;
        int ans = 0;
        for (int n : A) {
            add(&root, n);
            ans = max(ans, maxXor(&root, n));
        }
        return ans;
    }
};

class MyQueue {
public:

    stack<int> S1, S2;

    void push(int x) {
        while(!S1.empty()) {
            S2.push(S1.top());
            S1.pop();
        }

        S2.push(x);

        while(!S2.empty()) {
            S1.push(S2.top());
            S2.pop();
        }
    }

    int pop() {
        int x = S1.top();
        S1.pop();

        return x;
    }

    int peek() {
        return S1.top();
    }

    bool empty() {
        return S1.empty();
    }
};

int minSubArrayLen(int target, vector<int>& nums) {   
    int N = nums.size();
    int i = 0, sum = 0, ans = INT_MAX;

    for(int j = 0; j < N; j++) {
        sum += nums[j];

        while(sum >= target) {
            if(sum >= target) {
                ans = min(ans, j - i + 1);
            }
            sum -= nums[i++];
        }  
    }

    return ans == INT_MAX ? 0 : ans;
}

vector<int> canSeePersonsCount(vector<int>& A) {
    stack<int> S;
    int N = A.size();
    vector<int> ans(N, 0);

    for(int i = 0; i < N; i++) {
        // Monotonically Increasing Sequence
        while(S.size() && A[S.top()] <= A[i]) {
            ans[S.top()]++;
            S.pop();
        }

        if(S.size()) {
            ans[S.top()]++;
        }

        S.push(i);
    }    
    return ans;    
}

class Solution {
public:
    vector<vector<long long>> splitPainting(vector<vector<int>>& segments) {
        long long line[200001] = {};
        bool change[200001] = {};

        int maxEnd = -1;

        for(auto &e : segments) {
            int start = e[0], end = e[1], value = e[2];
            line[start] += value;
            line[end] -= value;
            change[start] = change[end] = true;
            maxEnd = max(maxEnd, end);
        }

        for(int i = 1; i <= maxEnd; i++) {
            line[i] += line[i - 1];
        }

        vector<vector<long long>> ans;

        for(int i = 0; i <= maxEnd;) {
            int start = i;
            while(i <= maxEnd && line[i] == line[start] && (i == start || !change[i])) i++;

            if(line[start]) {
                ans.push_back({start, i, line[start]});
            }
        }

        return ans;
    }
};

class Solution {
public:

    int dirs[4][2] = {{0, 1}, {1, 0}, {-1, 0}, {0, -1}};
    int M, N, startingColor;

    void dfs(vector<vector<int>> &image, int x, int y, int C) {

        image[x][y] = C;

        for(auto &dir : dirs) {
            int a = x + dir[0];
            int b = y + dir[1];

            if(a < 0 || b < 0 || a >= M || b >= N || image[a][b] != startingColor) continue;

            dfs(image, a, b, C);
        }
    }

    vector<vector<int>> floodFill(vector<vector<int>>& image, int sr, int sc, int color) {
        M = image.size();
        N = image[0].size();

        startingColor = image[sr][sc];

        if(color == startingColor) {
            return image;
        }

        dfs(image,  sr, sc, color);

        return image;
    }
};

class Solution {
public:

    bool isPalindrome(string &s, int i, int j) {
        while(i < j && s[i] == s[j]) {
            i++;
            j--;
        }
        return i >= j;
    }

    vector<vector<string>> ans;
    vector<string> temp;

    void dfs(string &s, int start) {
        if(start == s.size()) {
            ans.push_back(temp);
            return;
        }

        for(int i = start; i < s.length(); i++) {
            if(!isPalindrome(s, start, i)) continue;

            temp.push_back(s.substr(start, i - start + 1));
            dfs(s, i + 1);
            temp.pop_back();
        }
    }

    vector<vector<string>> partition(string s) {
        dfs(s, 0);
        return ans;
    }
};

class Solution {
public:
    int M, N;
    int dirs[4][2] = {{0, 1}, {1, 0}, {-1, 0}, {0, -1}};
    int maxGold = 0;


    void dfs(vector<vector<int>>& grid, int x, int y, int cnt) {

        // Store gold in current cell.
        int gold = grid[x][y];
        grid[x][y] = 0;

        cnt += gold;
        maxGold = max(maxGold, cnt);

        for(auto &dir : dirs) {
            int a = x + dir[0];
            int b = y + dir[1];

            if(a < 0 || b < 0 || a >= M || b >= N || grid[a][b] == 0) continue;

            dfs(grid, a, b, cnt);
        }

        grid[x][y] = gold;
    }

    int getMaximumGold(vector<vector<int>>& grid) {
        M = grid.size();
        N = grid[0].size();

        for(int i = 0; i < M; i++) {
            for(int j = 0; j < N; j++) {
                if(grid[i][j] == 0) continue;
                dfs(grid, i, j, 0);
            }
        }

        return maxGold;
    }
};

class Solution {
