int longestCommonSubsequence(string s, string t) {
    int M = s.size(), N = t.size();
    vector<vector<int>> dp(M + 1, vector<int>(N + 1, 0));

    for(int i = 1; i <= M; i++) {
        for(int j = 1; j <= N; j++) {
            if (s[i - 1] == t[j - 1]) {
                dp[i][j] = 1 + dp[i - 1][j - 1];
            } else {
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }

    return dp[M][N];
}

int countMaxOrSubsets(vector<int>& nums) {    
    int N = nums.size(), maxOr = 0;
    for(auto a : nums) maxOr |= a;

    int subsetCnt = 0;

    for(int mask = 0; mask < (1 << N); mask++) {
        int subsetOr = 0;
        for(int i = 0; i < N; i++) {
            if(mask >> i & 1) {
                subsetOr |= (nums[i]);
            }
        }

        if(subsetOr == maxOr) subsetCnt++;
    }

    return subsetCnt++;
}

bool canReach(vector<int>& A, int start) {
    if(start < 0 || start >= A.size() || A[start] < 0) return false;

    if(A[start] == 0) return true; 
    A[start] *= -1;

    return canReach(A, start + A[start]) || canReach(A, start - A[start]);
}

class LockingTree {
    vector<int> locked, parent;
    vector<vector<int>> child;
    int N;
    bool upwardValid(int i) {
        if (i == -1) return true;
        if (locked[i]) return false;
        return upwardValid(parent[i]);
    }
    bool downwardValid(int i) {
        if (locked[i]) return true;
        for (int ch : child[i]) {
            if (downwardValid(ch)) return true;
        }
        return false;
    }
    void downwardUnlock(int i) {
        locked[i] = 0;
        for (int ch : child[i]) {
            downwardUnlock(ch);
        }
    }
public:
    LockingTree(vector<int>& parent) : parent(parent) {
        N = parent.size();
        locked.assign(N, 0);
        child.assign(N, vector<int>());
        for (int i = 1; i < N; ++i) {
            child[parent[i]].push_back(i);
        }
    }

    bool lock(int num, int user) {
        if (locked[num] != 0) return false;
        locked[num] = user;
        return true;
    }

    bool unlock(int num, int user) {
        if (locked[num] != user) return false;
        locked[num] = 0;
        return true;
    }

    bool upgrade(int num, int user) {
        if (!upwardValid(num) || !downwardValid(num)) return false;
        downwardUnlock(num);
        locked[num] = user;
        return true;
    }
};

int minimumOperations(vector<int>& nums, int start, int goal) {
    queue<int> q;
    q.push(start);

    bool seen[1001] = {};
    int step = 0;

    seen[start] = true;

    while(q.size()) {
        int cnt = q.size();
        while(cnt--) {
            int n = q.front();
            q.pop();
            for(auto a : nums) {
                for(int next : {n + a, n - a, n ^ a}) {
                    if(next == goal) return step + 1;
                    if(next < 0 || next > 1000 || seen[next]) continue;
                    seen[next] = true;
                    q.push(next);
                }
            }
        }
        step++;
    }

    return -1;
}

int twoEggDrop(int n) {
