bool PredictTheWinner(vector<int>& nums) {
    int N = nums.size();
    unordered_map<int, unordered_map<int, int>> dp;
    for (int i = 0; i < N; ++i) dp[i][1] = nums[i];
    for (int len = 2; len <= N; ++len) {
        for (int i = 0; i <= N - len; ++i) {
            dp[i][len] = max(nums[i] - dp[i + 1][len - 1], nums[i + len - 1] - dp[i][len - 1]);
        }
    }
    return dp[0][N] >= 0;
}

class Solution {
public:

    int M, N;
    int dirs[4][2] = { {0, 1}, {1, 0}, {-1, 0}, {0, -1}};

    int minimumEffortPath(vector<vector<int>>& A) {

        M = A.size(), N = A[0].size();

        vector<vector<int>> minCost(M, vector<int>(N, INT_MAX));
        priority_queue<array<int, 3>, vector<array<int, 3>>, greater<>> pq;

        pq.push({0, 0, 0});
        minCost[0][0] = 0;

        while (pq.size()) {
            auto [e, x, y] = pq.top();
            pq.pop();

            if(e > minCost[x][y]) continue;
            if(x == M - 1 && y == N - 1) return minCost[x][y];

            for (auto &dir : dirs) {
                int a = x + dir[0];
                int b = y + dir[1];

                if (a < 0 || b < 0 || a >= M || b >= N) continue;
                int effort = max(e, abs(A[a][b] - A[x][y]));
                if(effort >= minCost[a][b]) continue;
                minCost[a][b] = effort;
                pq.push({effort, a, b});
            }
        }
        return -1;
    }
};

class Solution {
public:
    typedef array<int, 3> Item; // Cost, CityID, Stops Left

    int findCheapestPrice(int n, vector<vector<int>>& flights, int src, int dst, int k) {

        // Creation of Adjacent List
        vector<vector<pair<int, int>>> G(n);
        for(auto &e : flights) {
            int u = e[0], v = e[1], w = e[2];
            G[u].push_back({v, w});
        }

        k++;
        priority_queue<Item, vector<Item>, greater<>> pq;
        pq.push({0, src, k});

        vector<vector<int>> dist(k + 1, vector<int>(n, INT_MAX));

        for(int i = 0; i <= k; i++) {
            dist[i][src] = 0;
        }

        while (pq.size()) {
            auto [c, u, stop] = pq.top();
            pq.pop();

            if (c > dist[stop][u]) continue;
            if (u == dst) return c;
            if (stop == 0) continue;

            for (auto &[v, w] : G[u]) {
                if (dist[stop - 1][v] > c + w) {
                    dist[stop - 1][v] = c + w;
                    pq.push({dist[stop - 1][v], v, stop - 1});
                }
            }
        }

        return -1;
    }
};

class Solution {
public:
    int dirs[4][2] = { {0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    int minCost(vector<vector<int>>& grid) {

        int M = grid.size();
        int N = grid[0].size();

        int dist[100][100] = {};
        memset(dist, 0x3f, sizeof(dist));

        priority_queue<array<int, 3>, vector<array<int, 3>>, greater<>> pq;
        pq.push({ 0, 0, 0 });
        dist[0][0] = 0;

        while (pq.size()) {

            auto [cost, x, y] = pq.top();
            pq.pop();

            if (cost > dist[x][y]) continue;
            if (x == M - 1 && y == N - 1) return cost;

            for (int i = 0; i < 4; i++) {
                int a = x + dirs[i][0];
                int b = y + dirs[i][1];

                int newCost = cost + (grid[x][y] - 1 != i);

                if (a < 0 || b < 0 || a >= M || b >= N) continue;
                if (dist[a][b] > newCost) {
                    dist[a][b] = newCost;
                    pq.push({ newCost, a, b});
                }
            }
        }

        return 0;
    }
};

class Solution {
    vector<unordered_set<int>> memo;
private:
    bool dfs(vector<int> &A, int i, int k) {
        if (i == A.size() - 1) return true;
        if (memo[i].count(k)) return false; 
        int j = i + 1;
        for (int d = -1; d <= 1; ++d) {
            int move = k + d;
            if (move <= 0) continue;
            while (j < A.size() && A[j] - A[i] < move) ++j;
            if (j >= A.size()) return false;
            if (A[j] - A[i] == move && dfs(A, j, move)) return true;
        }
        memo[i].insert(k);
        return false;
    }
public:
    bool canCross(vector<int>& A) {
        memo.assign(A.size(), {});
        return dfs(A, 0, 0);
    }
};

vector<int> eventualSafeNodes(vector<vector<int>>& G) {
    int N = G.size();
    vector<vector<int>> R(N);
    vector<int> outdegree(N), safe(N), ans;
    queue<int> q;
    for (int i = 0; i < N; ++i) {
        for (int v : G[i]) {
            R[v].push_back(i);
        }
        outdegree[i] = G[i].size();
        if (outdegree[i] == 0) q.push(i);
    }
    while (q.size()) {
        int u = q.front();
        q.pop();
        safe[u] = 1;
        for (int v : R[u]) {
            if (--outdegree[v] == 0) q.push(v);
        }
    }
    for (int i = 0; i < N; ++i) {
        if (safe[i]) ans.push_back(i);
    }
    return ans;
}

class Solution {
    typedef pair<long, long> ipair;
public:
    int countPaths(int n, vector<vector<int>>& E) {
        vector<vector<pair<int, int>>> G(n);
        for (auto &e : E) {
            int u = e[0], v = e[1], t = e[2];
            G[u].emplace_back(v, t);
            G[v].emplace_back(u, t);
        }
        long mod = 1e9 + 7;
        vector<long> dist(n, LONG_MAX), cnt(n);
        priority_queue<ipair, vector<ipair>, greater<>> pq; // time, city
        dist[0] = 0;
        cnt[0] = 1;
        pq.emplace(0, 0);
        while (pq.size()) {
            auto [cost, u] = pq.top();
            pq.pop();
            if (cost > dist[u]) continue;
            for (auto &[v, time] : G[u]) {
                long c = cost + time;
                if (c < dist[v]) {
                    dist[v] = c;
                    cnt[v] = cnt[u];
                    pq.emplace(c, v);
                } else if (c == dist[v]) cnt[v] = (cnt[v] + cnt[u]) % mod;
            }
        }
        return cnt[n - 1];
    }
};

class Solution {
    ListNode* splitList(ListNode *head) {
        ListNode dummy, *p = &dummy, *q = &dummy;
        dummy.next = head;
        while (q && q->next) {
            q = q->next->next;
            p = p->next;
        }
        auto next = p->next;
        p->next = NULL;
        return next;
    }
    ListNode *mergeList(ListNode *a, ListNode *b) {
        ListNode head, *tail = &head;
        while (a && b) {
            ListNode *node;
            if (a->val <= b->val) {
                node = a;
                a = a->next;
            } else {
                node = b;
                b = b->next;
            }
            tail->next = node;
            tail = node;
        }
        if (a) tail->next = a;
        if (b) tail->next = b;
        return head.next;
    }
public:
    ListNode* sortList(ListNode* head) {
        if (!head || !head->next) return head;
        auto b = splitList(head);
        return mergeList(sortList(head), sortList(b));
    }
};

class Solution {
public:
    vector<vector<int> > G;
    vector<bool> seen;
    int target;

    double frogPosition(int n, vector<vector<int>>& edges, int t, int target) {
        if (n == 1) return 1.0;
        this->target = target;
        G.resize(n + 1, vector<int>());
        for (auto e : edges) {
            int u = e[0], v = e[1];
            G[u].push_back(v);
            G[v].push_back(u);
        }
        seen = vector<bool>(n + 1, false);

        return dfs(1, t);
    }

    double dfs(int i, int t) {
        // When time finishes and adjacent list is of size 1.
        if (i != 1 && G[i].size() == 1 || t == 0) {
            return i == target;
        }
        seen[i] = true;
        double res = 0;
        for (auto j : G[i]) {
            if (! seen[j]) {
                res += dfs(j, t - 1);
            }
        }
        return res / (G[i].size() - (i != 1));
    }
};

class Solution {
    int A = 0;
    pair<int, int> postorder(TreeNode* root)  {
        if (!root || (!root->left && !root->right)) return { 0, 0 };
        pair<int, int> ans;
        if (root->left) {
            auto left = postorder(root->left);
            ans.first = 1 + left.second;
        }
        if (root->right) {
            auto right = postorder(root->right);
            ans.second = 1 + right.first;
        }
        A = max({ A, ans.first, ans.second });
        return ans;
    }
public:
    int longestZigZag(TreeNode* root) {
        postorder(root);
        return A;
    }
};

class Solution {
    vector<int> v;
    void inorder(TreeNode *root) {
        if (!root) return;
        inorder(root->left);
        v.push_back(root->val);
        inorder(root->right);
    }
    TreeNode *build(int start, int end) {
        if (start >= end) return NULL;
        int mid = (start + end) / 2;
        auto node = new TreeNode(v[mid]);
        node->left = build(start, mid);
        node->right = build(mid + 1, end);
        return node;
    }
public:
    TreeNode* balanceBST(TreeNode* root) {
        inorder(root);
        return build(0, v.size());
    }
};

class Solution {
    bool match(ListNode *head, TreeNode *root) {
        if (!head) return true;
        if (!root) return false;
        if (head->val != root->val) return false;
        return match(head->next, root->left) || match(head->next, root->right);
    }
public:
    bool isSubPath(ListNode* head, TreeNode* root) {
        if (!head) return true;
        if (!root) return false;
        if (match(head, root)) return true;
        return isSubPath(head, root->left) || isSubPath(head, root->right);
    }
};

class Solution {
public:
    string subStrHash(string s, int p, int mod, int k, int target) {
        long h = 0, N = s.size(), pp = 1; // `pp` = p^k
        vector<long> hash(N);
        string r(rbegin(s), rend(s));
        for (int i = 0; i < N; ++i) {
            h = (h * p + (r[i] - 'a' + 1)) % mod; // push r[i] into the window
            if (i < k) pp = pp * p % mod;
            else h = (h - (r[i - k] - 'a' + 1) * pp % mod + mod) % mod; // pop r[i-k] out of the window
            if (i >= k - 1) hash[i] = h;
        }
        reverse(begin(hash), end(hash));
        for (int i = 0; i < N; ++i) {
            if (hash[i] == target) return s.substr(i, k);
        }
        return "";
    }
};

class Solution {
public:
    string subStrHash(string s, int p, int M, int k, int target) {

        long h = 0, pp = 1;
        int N = s.size();
        vector<long> hash(N);

        string r(rbegin(s), rend(s));

        for (int i = 0 ; i < N; i++) {
            h = (h * p + (r[i] - 'a' + 1)) % M;

            if (i < k) {
                pp = (pp * p) % M;
            } else {
                h = (h - (r[i - k] - 'a' + 1) * pp % M + M) % M;
            }

            if (i >= k - 1) {
                hash[i] = h;
            }
        }

        reverse(hash.begin(), hash.end());

        for (int i = 0; i < N; i++) {
            if (hash[i] == target) {
                return s.substr(i, k);
            }
        }

        return "";
    }
};

class Solution {
public:
    int distinctEchoSubstrings(string s) {

        int M = 1e8 + 7, cnt = 0;
        int N = s.length();
        vector<int> hash(N);

        for (int len = 1; len <= N / 2; len++) {

            long h = s[0] - 'a', p = 1;
            unordered_set<string> visited;

            for (int i = 1; i < N; i++) {
                if (i < len) {
                    h = (h * 26 + s[i] - 'a') % M; 
                    p = (p * 26) % M;
                } else {
                    h = ((h - (s[i - len] - 'a') * p) * 26 + s[i] - 'a') % M;
                    if (h < 0) h += M;

                    if ( i - 2 * len + 1 >= 0 && hash[i - len] == h) {
                        auto a = s.substr(i - 2 * len + 1, len);

                        if (visited.count(a)) continue;
                        visited.insert(a);

                        if (a == s.substr(i - len + 1, len)) cnt++;
                    }
                }
                hash[i] = h;
            }
        }

        return cnt;
    }
};

class Solution {
public:
    int findDuplicate(string s, int len) {
        int N = s.length();
        unsigned long long h = 0, d = 12582917, p = 1;
        unordered_set<unsigned long long> visited;

        for (int i = 0; i < N; i++) {
            h = h * d + s[i];

            if (i < len) {
                p *= d;
            } else {
                h -= s[i - len] * p;
            }

            if ( i >= len - 1) {
                if (visited.count(h)) return i - len + 1;
                visited.insert(h);
            }
        }
        return -1;
    }

    string longestDupSubstring(string s) {
        int L = 0, R = s.size() - 1, start = 0;
        while (L < R) {
            int M = (L + R + 1) / 2;
            int i = findDuplicate(s, M);

            if (i != -1) {
                L = M;
                start = i;
            } else {
                R = M - 1;
            }
        }

        return s.substr(start, L);
    }
};

