#include <valarray>
class Solution { //动态规划，时O(n^2)空O(n)
public:
    int lengthOfLIS(vector<int>& nums) {
        int n = nums.size();
        if (n==0){ //数组为空
            return 0;
        } 
        int dp[n];
        for(int i = 0; i<n;i++){
            dp[i]=1;
            for(int j = 0;j<i;j++){
                if(nums[i]>nums[j]){
                    dp[i]=max(dp[i],dp[j]+1);
                }
            }
        }
        return *max_element(dp,dp+n);    
    }
};

